style.css:
@-moz-document domain("google.com") {
/* --- GLOBAL STYLES & BACKGROUND --- */
    /* Set the background to pure white and use classic Arial font */
    body, #viewport, .srp #srp {
        background-color: #ffffff !important;
        font-family: Arial, sans-serif !important;
        color: #000000 !important;
    }

    /* Remove modern shadows, excess padding, rounded corners, and gradients */
    * {
        box-shadow: none !important;
        border-radius: 0 !important;
        background-image: none !important;
        transition: none !important;
    }

    /* --- MAIN SEARCH PAGE LAYOUT (The Google.com homepage) --- */

    /* Center the main search area and add classic top padding */
    #main, #content, .RNNxqb {
        display: block !important;
        width: 100% !important;
        margin: auto !important;
        text-align: center !important;
        padding-top: 100px !important;
        min-height: 80vh !important;
    }

    /* Remove the modern header bar and side language/footer on the main page */
    .gb_C, .gb_T, .gb_Ca, .o3j99 {
        display: none !important;
    }

    /* Adjust logo positioning */
    img.jfO6lb {
        margin-top: -150px !important;
    }

    /* --- SEARCH INPUT FIELD & BAR --- */

    /* Style the input container (remove the modern rounded pill effect) */
    .SDkEP {
        border: 1px solid #ccc !important; /* Basic grey border */
        box-shadow: none !important;
        max-width: 584px !important;
        margin: 0 auto !important;
        background-color: #fff !important;
    }

    /* Search input field itself */
    .gLFyf {
        font-size: 16px !important;
        color: #000 !important;
        height: 34px !important;
        padding: 0 10px !important;
        border: none !important;
        background: transparent !important;
    }

    /* Remove the modern icons inside the search box (search icon, voice icon) */
    .R7OaWc, .CqP0E {
        display: none !important;
    }


    /* --- SEARCH BUTTONS --- */

    /* Container for the buttons */
    .lJ9Rfd {
        margin-top: 25px !important; /* Space below search box */
    }

    /* Style the buttons (Google Search / I'm Feeling Lucky) */
    .gNO89b, .btnK {
        background-color: #f5f5f5 !important;
        border: 1px solid #c6c6c6 !important;
        color: #000 !important;
        font-size: 13px !important;
        padding: 8px 16px !important;
        cursor: pointer !important;
        margin: 0 5px !important;
        height: 36px !important;
        line-height: 20px !important;
        text-transform: none !important;
    }

    .gNO89b:hover, .btnK:hover {
        border-color: #999 !important;
        background-color: #ededed !important;
    }

    /* --- SEARCH RESULTS PAGE STYLES --- */

    /* Reset the header bar on the results page */
    #topstuff, #appbar {
        background-color: #fff !important;
        border-bottom: 1px solid #ccc !important;
        padding-bottom: 0 !important;
    }
    
    /* Remove knowledge panels and sidebars */
    #rhs {
        display: none !important;
    }

    /* Ensure main results column takes the space of the removed sidebar */
    #rcnt {
        max-width: 90% !important;
        margin: auto !important;
    }

    /* Reset result containers to classic layout */
    .g {
        max-width: 600px !important; /* Classic narrower width */
        margin: 0 0 1em 15% !important; /* Left-aligned on the page */
    }

    /* Result titles (blue links) */
    .LC20lb, .g h3 {
        color: #1a0dab !important; /* Classic blue link color */
        font-size: 18px !important;
        font-weight: normal !important;
        text-decoration: underline !important; /* Add classic underline */
    }

    /* Visited links (purple) */
    .LC20lb a:visited {
        color: #609 !important; /* Classic purple visited link */
        text-decoration: underline !important;
    }

    /* Snippets (black text) */
    .VwiC3b {
        color: #000000 !important; /* Classic black text */
        font-size: 13px !important;
        line-height: 1.4 !important;
    }

    /* Green URL (site link) */
    .UPmit {
        color: #006621 !important; /* Classic green URL color */
        font-style: normal !important;
    }
    
    /* Pagination (Next/Previous links) */
    #nav {
        text-align: left !important;
        margin-left: 15% !important;
    }

    .fl, .AaV0qd a {
        color: #0000ff !important; /* Force blue link color on pagination */
        text-decoration: underline !important;
        background-color: transparent !important;
    }
}
